<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{ChurchLocation,OrganisationUnit}; use Illuminate\Http\Request;
class ChurchLocationController extends Controller { public function index(){return view('admin.church_locations.index',['items'=>ChurchLocation::with('organisationUnit')->latest()->paginate(25),'units'=>OrganisationUnit::orderBy('name')->get(['id','name'])]);} public function store(Request $r){$d=$r->validate(['organisation_unit_id'=>'required|exists:organisation_units,id','name'=>'required|string|max:190','address'=>'nullable|string|max:500','latitude'=>'nullable|numeric|between:-90,90','longitude'=>'nullable|numeric|between:-180,180','service_times'=>'nullable|string|max:1000','youth_fellowship_times'=>'nullable|string|max:1000','phone'=>'nullable|string|max:40','email'=>'nullable|email|max:190']);ChurchLocation::create($d);return back()->with('success','Church location added.');} public function update(Request $r,ChurchLocation $churchLocation){$d=$r->validate(['organisation_unit_id'=>'required|exists:organisation_units,id','name'=>'required|string|max:190','address'=>'nullable|string|max:500','latitude'=>'nullable|numeric|between:-90,90','longitude'=>'nullable|numeric|between:-180,180','service_times'=>'nullable|string|max:1000','youth_fellowship_times'=>'nullable|string|max:1000','phone'=>'nullable|string|max:40','email'=>'nullable|email|max:190']);$churchLocation->update($d);return back()->with('success','Church location updated.');} public function destroy(ChurchLocation $churchLocation){$churchLocation->delete();return back()->with('success','Church location deleted.');} }
